<?php

declare(strict_types=1);

namespace Setono\CronBuilder;

use PHPUnit\Framework\TestCase;

final class CronBuilderTest extends TestCase
{
    /**
     * @test
     */
    public function it_builds(): void
    {
        $crontab = self::getCronBuilder()->build();

        $expected = <<<CRON
###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, $crontab);
    }

    /**
     * @test
     */
    public function it_builds_with_prod_env_set(): void
    {
        $crontab = self::getCronBuilder(['env' => 'prod'])->build();

        $expected = <<<CRON
###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/process.php --verbose
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, $crontab);
    }

    /**
     * @test
     */
    public function it_merges1(): void
    {
        $existingCrontab = <<<CRON


0 0 * * * /usr/bin/php /home/johndoe/public_html/other-job.php

###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/delete-files.php
###< Generated by PHPUnit ###




CRON;

        $expected = <<<CRON
0 0 * * * /usr/bin/php /home/johndoe/public_html/other-job.php

###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, CronBuilder::merge($existingCrontab, self::getCronBuilder()));
    }

    /**
     * @test
     */
    public function it_merges2(): void
    {
        $existingCrontab = ' ';

        $expected = <<<CRON
###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, CronBuilder::merge($existingCrontab, self::getCronBuilder()));
    }

    /**
     * @test
     */
    public function it_merges3(): void
    {
        $existingCrontab = <<<CRON
0 0 * * * /usr/bin/php /home/johndoe/public_html/other-job.php
CRON;

        $expected = <<<CRON
0 0 * * * /usr/bin/php /home/johndoe/public_html/other-job.php

###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, CronBuilder::merge($existingCrontab, self::getCronBuilder()));
    }

    /**
     * @test
     */
    public function it_does_not_add_the_same_file_twice(): void
    {
        $cronBuilder = self::getCronBuilder();
        $cronBuilder->addFile(__DIR__ . '/cronjobs/jobs.php');

        $expected = <<<CRON
###> Generated by PHPUnit ###
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/send-report.php --verbose # Run every day at midnight
0 0 * * * /usr/bin/php /home/johndoe/public_html/12/flush.php
###< Generated by PHPUnit ###

CRON;

        self::assertSame($expected, $cronBuilder->build());
    }

    /**
     * @test
     */
    public function it_throws_exception_when_jobs_file_does_not_exist(): void
    {
        $this->expectException(\InvalidArgumentException::class);

        (new CronBuilder())->addFile(__DIR__ . '/cronjobs/does_not_exist.php');
    }

    /**
     * @test
     *
     * @dataProvider invalidJobsFileProvider
     */
    public function it_throws_exception_when_jobs_file_is_invalid(string $jobsFile): void
    {
        $this->expectException(\InvalidArgumentException::class);

        (new CronBuilder())
            ->addFile(__DIR__ . '/cronjobs_invalid/' . $jobsFile)
            ->build()
        ;
    }

    /**
     * @return \Generator<array-key, array{string}>
     */
    public function invalidJobsFileProvider(): \Generator
    {
        yield ['jobs1.php'];
        yield ['jobs2.php'];
        yield ['jobs3.php'];
        yield ['jobs4.php'];
    }

    /**
     * @param array<string, mixed> $context
     */
    private static function getCronBuilder(array $context = []): CronBuilder
    {
        $cronBuilder = new CronBuilder(__DIR__ . '/cronjobs');
        $cronBuilder->delimiter = 'Generated by PHPUnit';

        $cronBuilder
            ->context
                ->set('release_path', '/home/johndoe/public_html')
                ->set('args', '--verbose')
                ->set('release_number', 12)
                ->set('bin/php', '/usr/bin/php')
        ;

        /** @var mixed $value */
        foreach ($context as $key => $value) {
            $cronBuilder->context->set($key, $value);
        }

        return $cronBuilder;
    }
}
